// Ignore and clear any outdated workers.dev URL stored by previous versions.
localStorage.removeItem('safepass_api');
const API=window.location.origin;
let tab='user', chosen='', challenge='', consent=false, events=[], last=null; let userRentals=[];let partnerRentals=[];let lastMultiSync=0; let scan=null, liveTimer=null, partnerRental='';
