const RENTAL_STORE='safepass_demo_rental_v1';
const PARTNER_RENTAL_STORE='safepass_partner_rental_v1';
function restoreRental(){try{const v=JSON.parse(localStorage.getItem(RENTAL_STORE)||'null');return v&&typeof v.rental_id==='string'&&/^[0-9a-f-]{36}$/i.test(v.rental_id)?v:null}catch{return null}}
function saveRental(v){if(v?.rental_id){localStorage.setItem(RENTAL_STORE,JSON.stringify({rental_id:v.rental_id,token_id:v.token_id||'',expires_at:v.expires_at||'',status:v.status||'ACTIVE',item:v.item||''}))}}
function savePartnerRental(id){if(id&&/^[0-9a-f-]{36}$/i.test(id))localStorage.setItem(PARTNER_RENTAL_STORE,id)}
last=restoreRental();
partnerRental=localStorage.getItem(PARTNER_RENTAL_STORE)||'';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function demoId(){let x=localStorage.getItem('sp_device');if(!x){x=crypto.randomUUID();localStorage.setItem('sp_device',x)}return x}
function safeHeaderValue(value,label){if(/[^\x20-\x7E]/.test(value))throw Error(label+'에 한글이나 허용되지 않는 문자가 포함되어 있습니다. 접근 키를 확인하거나 초기화하세요.');return value}
async function api(path,body,method='POST'){if(!API)throw Error('API 주소 미설정: 설정에서 SafePass Worker URL을 입력하세요.');const partnerKey=sessionStorage.getItem('sp_partner_key')||'';let r=await fetch(API+path,{method,headers:{'Content-Type':'application/json','X-Demo-Device':demoId(),...(path==='/api/partner/register'?{}:{'X-Partner-Key':safeHeaderValue(partnerKey,'대여처 접근 키')})},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||`요청 실패(${r.status})`);return j}
function nav(t){if((t==='partner'||t==='admin')&&!partnerModeUnlocked){openModeModal();return;}if(scan){scan.stop().catch(()=>{});scan=null}if(liveTimer){clearInterval(liveTimer);liveTimer=null}tab=t;saveView();render()}
let toastTimer=null;function toast(s){const el=$('#message');if(!el)return;el.textContent=String(s);if(toastTimer)clearTimeout(toastTimer);const current=el;toastTimer=setTimeout(()=>{if(current.isConnected)current.textContent=''},6000)}
