const VIEW_KEY='safepass_view_v071', NOTICE_KEY='safepass_expiry_notices_v071';
const getNotices=()=>{try{return JSON.parse(localStorage.getItem(NOTICE_KEY)||'[]')}catch{return []}};
function saveView(){sessionStorage.setItem(VIEW_KEY,JSON.stringify({tab,userSubtab,partnerSection}));}
function restoreView(){try{const v=JSON.parse(sessionStorage.getItem(VIEW_KEY)||'{}');userSubtab=['home','tokens','history'].includes(v.userSubtab)?v.userSubtab:'home';partnerSection=['home','overdue','manage'].includes(v.partnerSection)?v.partnerSection:'home';tab=v.tab==='partner'?'partner':'user';}catch{tab='user'} }
function notifyExpiry(id,item){const key='expired:'+id;const notices=getNotices();if(notices.some(x=>x.id===key))return;notices.unshift({id:key,message:`${item||'대여 물품'} 대여시간이 종료되었습니다. 반납 여부를 확인해 주세요.`,at:new Date().toISOString()});localStorage.setItem(NOTICE_KEY,JSON.stringify(notices.slice(0,30)));const count=$('#expiryNoticeCount');if(count)count.textContent=String(notices.length);if(tab==='user'){const out=$('#expiryBanner');if(out)out.innerHTML=`<div class="expiry-alert" role="alert">${esc(notices[0].message)}</div>`} if(document.visibilityState==='visible'&&'Notification' in window&&Notification.permission==='granted'){try{new Notification('SafePass 대여시간 종료',{body:notices[0].message,tag:key})}catch{}}}
async function openNotifications(){let list=getNotices();try{const remote=await api('/api/user/notices',null,'GET');const known=new Set(list.map(x=>x.id));for(const x of remote.notices||[]){if(!known.has(x.id))list.unshift({id:x.id,message:x.message,at:x.at})}localStorage.setItem(NOTICE_KEY,JSON.stringify(list.slice(0,100)))}catch(e){}const target=$('#message');if(target){target.innerHTML=list.length?`<div class="expiry-alert" role="status"><strong>알림 내역</strong>${list.map(x=>`<p>${esc(x.message)}</p>`).join('')}</div>`:'<div class="hint">새로운 알림이 없습니다.</div>';target.scrollIntoView({block:'start',behavior:'smooth'})}}
restoreView();
adminSessionKey=sessionStorage.getItem('sp_admin_session_key')||'';partnerModeUnlocked=!!adminSessionKey;

