function icon(name,cls=''){return `<span class="svg-icon ${cls}" aria-hidden="true">${ICONS[name]||''}</span>`}
function shell(content){const inPartner=tab==='partner'||tab==='admin';document.body.classList.toggle('partner-mode',inPartner);$('#app').innerHTML=`<header class="app-header"><strong class="wordmark">${inPartner?'SafePass Partner':'SafePass'}</strong><nav class="desktop-top-nav" aria-label="${inPartner?'대여자':'이용자'} 상단 메뉴">${inPartner?`<button type="button" data-partner-section="home" class="${partnerSection==='home'?'active':''}" aria-current="${partnerSection==='home'?'page':'false'}"><span>홈</span></button><button type="button" data-partner-section="manage" class="${partnerSection==='manage'?'active':''}" aria-current="${partnerSection==='manage'?'page':'false'}"><span>통합 관리</span></button><button type="button" data-partner-section="overdue" class="${partnerSection==='overdue'?'active':''}" aria-current="${partnerSection==='overdue'?'page':'false'}"><span>이용자 조회</span></button>`:`<button type="button" data-sub="home" class="${userSubtab==='home'?'active':''}" aria-current="${userSubtab==='home'?'page':'false'}"><span>홈</span></button><button type="button" data-sub="tokens" class="${userSubtab==='tokens'?'active':''}" aria-current="${userSubtab==='tokens'?'page':'false'}"><span>보증내역</span></button><button type="button" data-sub="history" class="${userSubtab==='history'?'active':''}" aria-current="${userSubtab==='history'?'page':'false'}"><span>열람이력</span></button>`}</nav><div class="header-actions">${!inPartner?`<button class="icon-button" id="notificationButton" aria-label="알림">${icon('bell','sm')}</button>`:''}<button class="icon-button" id="modeButton" aria-label="${inPartner?'이용자 화면으로':'대여자 모드 진입'}">${inPartner?icon('door','sm'):icon('person','sm')}</button></div></header><div class="notice notice-marquee" aria-label="시험용 서비스 안내"><div class="notice-marquee-track"><span>실제 모바일신분증이 아닌 시험용 서비스입니다. 개인정보를 입력하지 마세요.</span><span aria-hidden="true">실제 모바일신분증이 아닌 시험용 서비스입니다. 개인정보를 입력하지 마세요.</span></div></div><main class="app-main"><div id="message" role="status" aria-live="polite"></div>${content}</main>${tab==='user'?`<nav class="bottom-nav" aria-label="이용자 메뉴"><button data-sub="home" class="${userSubtab==='home'?'active':''}">${icon('home','nav')}<span class="nav-label">홈</span></button><button data-sub="tokens" class="${userSubtab==='tokens'?'active':''}">${icon('card','nav')}<span class="nav-label">보증내역</span></button><button data-sub="history" class="${userSubtab==='history'?'active':''}">${icon('history','nav')}<span class="nav-label">열람이력</span></button></nav>`:`<nav class="partner-bottom" aria-label="대여자 메뉴"><button id="partnerHomeNav" class="${partnerSection==='home'?'active':''}">${icon('home','nav')}<span class="nav-label">홈</span></button><button id="partnerManageNav" class="${partnerSection==='manage'?'active':''}">${icon('settings','nav')}<span class="nav-label">통합 관리</span></button><button id="partnerOverdueNav" class="${partnerSection==='overdue'?'active':''}">${icon('person','nav')}<span class="nav-label">이용자 조회</span></button></nav>`}<footer>SafePass · 모바일신분증 기반 대여 보증 PoC (시험용)</footer><div id="modeModal" class="mode-modal" hidden></div>`;
$('#modeButton').onclick=()=>{if(inPartner){partnerModeUnlocked=false;adminSessionKey='';sessionStorage.removeItem('sp_admin_session_key');partnerSection='home';userSubtab='home';nav('user')}else openModeModal()};
const bell=$('#notificationButton');if(bell)bell.onclick=openNotifications;
document.querySelectorAll('[data-sub]').forEach(b=>b.onclick=()=>{userSubtab=b.dataset.sub;saveView();nav('user')});
document.querySelectorAll('[data-partner-section]').forEach(b=>b.onclick=()=>{partnerSection=b.dataset.partnerSection;nav('partner');if(partnerSection==='overdue')loadOverdue();else if(partnerSection==='manage')loadAdmin();});
if($('#partnerHomeNav'))$('#partnerHomeNav').onclick=()=>{partnerSection='home';nav('partner');};
if($('#partnerOverdueNav'))$('#partnerOverdueNav').onclick=()=>{partnerSection='overdue';nav('partner');loadOverdue();};
if($('#partnerManageNav'))$('#partnerManageNav').onclick=()=>{partnerSection='manage';nav('partner');loadAdmin();};

if($('#openPartner'))$('#openPartner').onclick=()=>nav('partner');}
function openModeModal(){const modal=$('#modeModal');modal.hidden=false;modal.innerHTML=`<div class="mode-overlay"><form class="mode-dialog" id="modeForm"><button type="button" id="closeMode" class="dialog-close" aria-label="닫기">×</button><span class="mode-crest">${icon('lock','lg')}</span><h2>대여자 모드 진입</h2><p>관리자 시험 키를 입력해 대여처 운영 화면으로 전환합니다.</p><label for="modePassword">관리자 시험 키</label><input type="password" id="modePassword" autocomplete="off" required placeholder="관리자 시험 키 입력"><p class="mode-error" id="modeError" role="alert"></p><button id="confirmMode" type="submit">대여자 모드로 전환</button><small>서버 인증 후 이 탭의 세션 동안 유지되며, 모드 종료 시 삭제됩니다.</small></form></div>`;$('#closeMode').onclick=()=>modal.hidden=true;modal.querySelector('.mode-overlay').onclick=e=>{if(e.target===e.currentTarget)modal.hidden=true};$('#modeForm').onsubmit=async e=>{e.preventDefault();const pass=$('#modePassword').value;const btn=$('#confirmMode');btn.disabled=true;btn.textContent='인증 확인 중…';try{const r=await fetch(API+'/api/admin/overview',{headers:{'X-Admin-Key':safeHeaderValue(pass,'관리자 키')},cache:'no-store'});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(r.status===401?'관리자 시험 키가 일치하지 않습니다.':data.error||`인증 실패 (${r.status})`);adminSessionKey=pass;sessionStorage.setItem('sp_admin_session_key',pass);partnerModeUnlocked=true;partnerSection='home';modal.hidden=true;nav('partner');}catch(err){const el=$('#modeError');if(el)el.textContent=err.message;}finally{btn.disabled=false;btn.textContent='대여자 모드로 전환'}};setTimeout(()=>$('#modePassword')?.focus(),0)}
